function classify(s){ if(s>=13) return '轻度/正常'; if(s>=9) return '中度'; return '重度'; }
function gcs(eye, verbal, motor){ eye=+eye; verbal=+verbal; motor=+motor;
  if(eye<1||eye>4||verbal<1||verbal>5||motor<1||motor>6) return {error:'评分范围错误（眼1-4/语言1-5/运动1-6）'};
  var s=eye+verbal+motor; return {total:s, classify:classify(s)}; }
var EXPORTS={gcs:gcs, classify:classify};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GlasgowForgePure = EXPORTS; }
